-- Clean bootstrap 006: security monitoring schema and baseline thresholds only.
CREATE TABLE IF NOT EXISTS public.security_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event_type text NOT NULL,user_id uuid REFERENCES auth.users(id) ON DELETE SET NULL,success boolean NOT NULL,ip_address inet,user_agent text,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.security_thresholds(name text PRIMARY KEY,category text NOT NULL,value numeric NOT NULL,description text,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.security_anomalies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES auth.users(id) ON DELETE SET NULL,category text NOT NULL,severity text NOT NULL CHECK(severity IN('low','medium','high','critical')),title text NOT NULL,description text,risk_score numeric CHECK(risk_score BETWEEN 0 AND 100),status text NOT NULL DEFAULT 'open',metadata jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),resolved_at timestamptz);
CREATE TABLE IF NOT EXISTS public.failed_login_attempts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text,ip_address inet,failure_reason text,attempted_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.user_risk_scores(user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,overall_score numeric NOT NULL DEFAULT 0 CHECK(overall_score BETWEEN 0 AND 100),updated_at timestamptz NOT NULL DEFAULT now());
INSERT INTO public.security_thresholds(name,category,value,description) VALUES('failed_login_threshold','authentication',5,'Failed logins before alert'),('high_value_transaction_cdf','transaction',10000000,'High value CDF transaction'),('inventory_variance_percent','inventory',20,'Inventory variance alert threshold') ON CONFLICT(name) DO NOTHING;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['security_events','security_thresholds','security_anomalies','failed_login_attempts','user_risk_scores'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('DROP POLICY IF EXISTS security_admin ON public.%I',t); EXECUTE format('CREATE POLICY security_admin ON public.%I FOR SELECT TO authenticated USING(public.is_admin())',t); END LOOP; END $$;
CREATE OR REPLACE FUNCTION public.detect_suspicious_transactions() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_admin() THEN RAISE EXCEPTION 'Admin role required'; END IF; INSERT INTO public.security_anomalies(category,severity,title,description,risk_score,metadata) SELECT 'transaction','high','High-value sales order','Order exceeds configured threshold',70,jsonb_build_object('order_id',so.id,'amount',so.total_amount) FROM public.sales_orders so WHERE so.total_amount>COALESCE((SELECT value FROM public.security_thresholds WHERE name='high_value_transaction_cdf'),10000000) AND NOT EXISTS(SELECT 1 FROM public.security_anomalies a WHERE a.metadata->>'order_id'=so.id::text AND a.status='open'); END $$;
CREATE OR REPLACE FUNCTION public.detect_unauthorized_access() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_admin() THEN RAISE EXCEPTION 'Admin role required'; END IF; INSERT INTO public.security_anomalies(user_id,category,severity,title,description,risk_score,metadata) SELECT NULL,'authentication','high','Repeated login failures','Failure threshold exceeded',75,jsonb_build_object('email',email,'attempts',count(*)) FROM public.failed_login_attempts WHERE attempted_at>now()-interval '1 hour' GROUP BY email HAVING count(*)>=COALESCE((SELECT value FROM public.security_thresholds WHERE name='failed_login_threshold'),5) AND NOT EXISTS(SELECT 1 FROM public.security_anomalies a WHERE a.metadata->>'email'=failed_login_attempts.email AND a.status='open'); END $$;
CREATE OR REPLACE FUNCTION public.detect_inventory_anomalies() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_admin() THEN RAISE EXCEPTION 'Admin role required'; END IF; INSERT INTO public.security_anomalies(category,severity,title,description,risk_score,metadata) SELECT 'inventory','medium','Inventory below reorder level','Stock requires attention',50,jsonb_build_object('inventory_id',i.id,'quantity',i.quantity) FROM public.inventory_stock i WHERE i.quantity<=i.reorder_level AND NOT EXISTS(SELECT 1 FROM public.security_anomalies a WHERE a.metadata->>'inventory_id'=i.id::text AND a.status='open'); END $$;
CREATE OR REPLACE FUNCTION public.calculate_user_risk_scores() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_admin() THEN RAISE EXCEPTION 'Admin role required'; END IF; INSERT INTO public.user_risk_scores(user_id,overall_score,updated_at) SELECT p.id,least(100,COALESCE(sum(a.risk_score),0)/greatest(count(a.id),1)),now() FROM public.user_profiles p LEFT JOIN public.security_anomalies a ON a.user_id=p.id AND a.status='open' GROUP BY p.id ON CONFLICT(user_id) DO UPDATE SET overall_score=EXCLUDED.overall_score,updated_at=now(); END $$;
